Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-597-first-babylonian-capture-of-jerusalem-20"]||=( {} ),{"title":"הכיבוש הבבלי הראשון של ירושלים","location":"ירושלים / ממלכת יהודה","story":"נבוכדנצר השני כבש את ירושלים לאחר מרד של יהודה. המלך יהויכין, אנשי החצר, חיילים, בעלי מלאכה ואליטות אחרות הוגלו לבבל. הגליה גדולה ראשונה זו קדמה לחורבן המאוחר יותר של ירושלים ובית המקדש הראשון.","context":"האירוע נכלל כדי להציג הן אלימות שהופנתה כלפי קהילות יהודאיות והן עימותים שבהם שליטים או פלגים יהודאיים היו בעצמם צד פעיל.","aftermath":"האירוע החל שלב מרכזי בגלות הבבלית והחליש את ממלכת יהודה לפני החורבן הסופי.","sourceStatus":"ראיות חזקות מן הכרוניקה הבבלית ומן המקרא"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-597-first-babylonian-capture-of-jerusalem-20"]||=( {} ),{"title":"الاستيلاء البابلي الأول على القدس","location":"القدس / مملكة يهوذا","story":"استولى نبوخذ نصر الثاني على القدس بعد تمرد يهوذا. ورُحّل الملك يهوياكين وأفراد البلاط والجنود والحرفيون ونخب أخرى إلى بابل. وسبق هذا الترحيل الكبير الأول التدمير اللاحق للقدس والهيكل الأول.","context":"أُدرج الحدث لإظهار العنف الموجه إلى المجتمعات اليهودية وكذلك الصراعات التي كان فيها حكام أو فصائل يهودية أطرافًا فاعلة.","aftermath":"بدأ الحدث مرحلة رئيسية من السبي البابلي وأضعف مملكة يهوذا قبل دمارها النهائي.","sourceStatus":"أدلة قوية من السجل البابلي ومن النصوص التوراتية"});
